0\u0437\u0430\u043d\u0438\u0435 \u0447\u0435\u0440\u0435\u0437 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432\u043d\u0443\u0442\u0440\u0438 \u0431\u043b\u043e\u043a\u0430. \u041e\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430: \u0434\u0435\u043b\u0438\u0442\u0435\u043b\u0438/\u043a\u0440\u0430\u0442\u043d\u044b\u0435 \u0441\u0443\u0442\u043a\u0430\u043c (\u043f\u0440\u0438 10-\u043c\u0438\u043d \u0448\u0430\u0433\u0435 \u0441\u0443\u0442\u043a\u0438=144 \u0448\u0430\u0433\u0430): {6, 12, 24, 48, 96, 144}.\n**\u0412\u0435\u0442\u043a\u0430 \u0411 \u2014 period \u043a\u0430\u043a \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 \u0438\u0437 \u0441\u043f\u0435\u043a\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0438** (FFT top-k, \u0441\u0442\u0438\u043b\u044c TimesNet) \u043b\u0438\u0431\u043e \u0435\u0433\u043e override: \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0437\u0430\u0434\u0430\u0451\u0442 \u0447\u0430\u0441\u0442\u043e\u0442\u0443, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u0433\u0430\u0440\u043c\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0430\u044f/\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430; \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u0438\u0435 \u0447\u0435\u0440\u0435\u0437 \u0432\u044b\u0431\u043e\u0440 \u0447\u0430\u0441\u0442\u043e\u0442/\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435. \u0421\u0435\u0442\u043a\u0430 \u0442\u0430 \u0436\u0435, \u043d\u043e \u0442\u0440\u0430\u043a\u0442\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u044f/\u043f\u0435\u0440\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0430\u0432\u0442\u043e\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f; \u0442\u043e\u0447\u043a\u0430 \u00ab\u0430\u0432\u0442\u043e\u00bb \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430.\n\n**\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f (greppable-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043f\u043e \u043a\u043e\u0434\u0443, \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432):**\n1. \u0438\u043c\u044f \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u0430 (`period|cycle|seasonal_period|period_len|patch*`) \u0432 `argparse`/\u043a\u043e\u043d\u0444\u0438\u0433\u0435;\n2. default-\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0438\u0437 \u043a\u043e\u043d\u0444\u0438\u0433\u0430 \u2192 \u0431\u0430\u0437\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u00a76(i);\n3. \u043c\u0435\u0441\u0442\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0432 forward-\u0433\u0440\u0430\u0444\u0435 (\u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f/\u0441\u043a\u043e\u043b\u044c\u0437\u044f\u0449\u0435\u0435 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u2192 \u0432\u0435\u0442\u043a\u0430 \u0410; FFT/top-k/\u0447\u0430\u0441\u0442\u043e\u0442\u043d\u044b\u0439 \u0444\u0438\u043b\u044c\u0442\u0440 \u2192 \u0432\u0435\u0442\u043a\u0430 \u0411);\n4. assert/\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0438, \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u044e\u0449\u0438\u0435 period \u0441 `seq_len` (\u0434\u043b\u044f \u00a74).\n\u0415\u0441\u043b\u0438 \u043a\u043e\u0434 \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0438 \u0442\u043e \u0438 \u0434\u0440\u0443\u0433\u043e\u0435 \u2014 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0432\u0435\u0442\u043a\u0430, \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0430\u044f \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044e \u0432 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u0438\u0438; \u0432\u0442\u043e\u0440\u0430\u044f \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u043a\u0430\u043a \u043d\u0435\u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c\u0430\u044f.\n\n## 3. \u0414\u0430\u043d\u043d\u044b\u0435 \u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u04102\u2013\u04103 \u0438\u0437 \u00a710; \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u043f\u043e \u00a710)\nETTm1: 10-\u043c\u0438\u043d\u0443\u0442\u043d\u044b\u0439 \u0448\u0430\u0433, 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432, ~69 680 \u0441\u0442\u0440\u043e\u043a (2016-07-01\u20262018-06-30). \u0425\u0440\u043e\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043f\u043b\u0438\u0442 6:2:2 (12/4/4 \u043c\u0435\u0441\u044f\u0446\u0430), \u043a\u0430\u043a \u0432 ETT-\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0435 Informer: train \u2014 \u043f\u0435\u0440\u0432\u044b\u0435 12 \u043c\u0435\u0441., val \u2014 \u0441\u043b\u0435\u0434. 4, test \u2014 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 4. \u0421\u043a\u0430\u043b\u0435\u0440 (\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 instance/dataset scaler \u0438\u0437 \u043a\u043e\u0434\u0430) \u043f\u043e\u0434\u0433\u043e\u043d\u044f\u0435\u0442\u0441\u044f \u0422\u041e\u041b\u042c\u041a\u041e \u043d\u0430 train. \u0410\u0432\u0442\u043e\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 period (\u0432\u0435\u0442\u043a\u0430 \u0411, \u0442\u043e\u0447\u043a\u0430 \u00ab\u0430\u0432\u0442\u043e\u00bb) \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e train-\u043e\u0442\u0440\u0435\u0437\u043a\u0443. Val \u2014 \u0440\u0430\u043d\u043d\u0438\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432/\u0432\u044b\u0431\u043e\u0440 \u044d\u043f\u043e\u0445; test \u2014 \u043e\u0434\u043d\u043e\u043a\u0440\u0430\u0442\u043d\u0430\u044f \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438. \u0423\u0442\u0435\u0447\u043a\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u0435\u043c, \u0447\u0442\u043e \u043d\u0438\u043a\u0430\u043a\u0438\u0435 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 (\u0441\u043a\u0430\u043b\u0435\u0440, \u0441\u043f\u0435\u043a\u0442\u0440, period) \u043d\u0435 \u0432\u0438\u0434\u044f\u0442 val/test.\n\n## 4. \u0424\u0430\u043a\u0442\u043e\u0440\u043d\u044b\u0439 \u043f\u043b\u0430\u043d\n**\u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0444\u0430\u043a\u0442\u043e\u0440:** `period` \u2208 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 **{6, 12, 24, 48, 96, 144}** (\u0443\u043a\u0430\u0437\u0430\u043d\u0438\u0435 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f) + 2 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0442\u043e\u0447\u043a\u0438: default \u0438\u0437 \u043a\u043e\u043d\u0444\u0438\u0433\u0430 (\u00a76i) \u0438 \u0430\u0432\u0442\u043e\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0441\u043f\u0435\u043a\u0442\u0440\u0443, \u0435\u0441\u043b\u0438 \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442. \u0418\u0442\u043e\u0433\u043e \u2264 8 \u0443\u0441\u043b\u043e\u0432\u0438\u0439.\n**\u041f\u0440\u043e\u0435\u043a\u0442\u043d\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435:** `seq_len \u2265 2\u00b7period` (\u043c\u0438\u043d\u0438\u043c\u0443\u043c 2 \u043f\u043e\u043b\u043d\u044b\u0445 \u0446\u0438\u043a\u043b\u0430 \u0432\u043e \u0432\u0445\u043e\u0434\u0435, L=96 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e). \u041d\u0430\u0440\u0443\u0448\u0430\u044e\u0449\u0438\u0435 \u0442\u043e\u0447\u043a\u0438 (\u043f\u0440\u0438 L=96: period \u2208 {96, 144}) \u041d\u0415 \u0432\u044b\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f, \u0430 \u0437\u0430\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0432 \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440 \u00ab\u043c\u0430\u043b\u043e \u0446\u0438\u043a\u043b\u043e\u0432 \u0432\u043e \u0432\u0445\u043e\u0434\u0435\u00bb (L/period < 2) \u0438 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0441\u0435\u0442\u043a\u0438.\n**\u0412\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 (\u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440\u0430 \u043d\u0430\u0440\u0443\u0448\u0438\u0442\u0435\u043b\u0435\u0439):** L \u2208 {96, 192, 336}, \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u043c\u044b\u0439 \u043b\u0438\u0448\u044c \u043a \u0442\u043e\u0447\u043a\u0430\u043c \u0441 L/period < 2 \u043f\u0440\u0438 \u0431\u0430\u0437\u043e\u0432\u043e\u043c L=96 \u2014 \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u0434\u0435\u043b\u0438\u0442\u044c \u044d\u0444\u0444\u0435\u043a\u0442 \u043c\u0430\u043b\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 \u0446\u0438\u043a\u043b\u043e\u0432 \u043e\u0442 \u0441\u0430\u043c\u043e\u0433\u043e period (\u00a76iii).\n**\u0424\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f:** \u0432\u0441\u0435 \u043f\u0440\u043e\u0447\u0438\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u2014 \u0438\u0437 \u043a\u043e\u043d\u0444\u0438\u0433\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u043c\u043e\u0434\u0435\u043b\u044c, d_model, \u0441\u043b\u043e\u0438, lr, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440, batch, dropout, \u0447\u0438\u0441\u043b\u043e \u044d\u043f\u043e\u0445/\u0440\u0430\u043d\u043d\u0438\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432, len(label_len) \u0438 \u0442.\u043f.); \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u044b H \u2208 {96, 192, 336, 720}; \u0434\u043b\u0438\u043d\u0430 \u0432\u0445\u043e\u0434\u0430 L=96 \u0434\u043b\u044f \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0441\u0435\u0442\u043a\u0438; \u0446\u0435\u043b\u0435\u0432\u044b\u0435 \u043a\u0430\u043d\u0430\u043b\u044b \u2014 \u043a\u0430\u043a \u0432 \u043a\u043e\u043d\u0444\u0438\u0433\u0435 (\u0441\u043c. \u00a75 \u043f\u0440\u043e OT).\n\n## 5. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 (\u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c)\n- **\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f:** MAE, \u0443\u0441\u0440\u0435\u0434\u043d\u0451\u043d\u043d\u0430\u044f \u043f\u043e \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0430\u043c {96, 192, 336, 720} \u0438 \u043f\u043e \u0446\u0435\u043b\u0435\u0432\u044b\u043c \u043a\u0430\u043d\u0430\u043b\u0430\u043c (7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432 \u043f\u043e ETT-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0443).\n- **\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f:** MSE \u0432 \u0442\u0435\u0445 \u0436\u0435 \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u044f\u0445.\n- **\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438:** MAE \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0443 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043b\u0438 \u0437\u043d\u0430\u043a/\u043f\u043e\u0440\u044f\u0434\u043e\u043a \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0441 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043e\u043c).\n- **OT-\u0441\u0432\u043e\u0434\u043a\u0430:** \u043f\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0443 Informer c_out=7, \u0442.\u0435. \u0432\u0441\u0435 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432 \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0446\u0435\u043b\u0435\u0432\u044b\u0435; \u043f\u0440\u0438 \u044d\u0442\u043e\u043c OT \u043e\u0431\u044b\u0447\u043d\u043e \u0438 \u0435\u0441\u0442\u044c \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u0443\u044e\u0449\u0438\u0439 \u043a\u0430\u043d\u0430\u043b. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e \u0432\u0435\u0434\u0451\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0432\u043e\u0434\u043a\u0430 MAE/MSE \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u043a\u0430\u043d\u0430\u043b\u0443 OT (\u0442\u0435\u043c \u0436\u0435 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u043c \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0435\u043c). \u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0446\u0435\u043b\u0435\u0432\u044b\u0445 \u043a\u0430\u043d\u0430\u043b\u043e\u0432 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u043e \u043a\u043e\u0434\u0443: `c_out`/`data_dim`/\u0440\u0430\u0437\u043c\u0435\u0440 y \u0432 \u0434\u0430\u0442\u0430\u0441\u0435\u0442-\u043a\u043b\u0430\u0441\u0441\u0435 (\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 A2-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b, \u00a710).\n\n## 6. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n(i) **\u0411\u0430\u0437\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u2014 default-config:** \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 period \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0432 \u0442\u043e\u0439 \u0436\u0435 \u0441\u0435\u0442\u043a\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432; \u0432\u0441\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u2014 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0435\u0433\u043e \u0438 \u043c\u0435\u0436\u0434\u0443 \u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u0441\u0435\u0442\u043a\u0438.\n(ii) **\u00ab\u041d\u0443\u043b\u0435\u0432\u043e\u0439\u00bb \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c:** period, \u0437\u0430\u0432\u0435\u0434\u043e\u043c\u043e \u043d\u0435\u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441 \u0441\u0443\u0442\u043e\u0447\u043d\u044b\u043c (144) \u0438 \u043d\u0435\u0434\u0435\u043b\u044c\u043d\u044b\u043c (1008) \u0446\u0438\u043a\u043b\u0430\u043c\u0438 ETTm1, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 **period = 37** (\u043f\u0440\u043e\u0441\u0442\u043e\u0435 \u0447\u0438\u0441\u043b\u043e, \u043d\u0435 \u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c \u0441\u0443\u0442\u043e\u043a). \u0421\u043b\u0443\u0436\u0438\u0442 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u043e\u043c, \u0447\u0442\u043e \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f \u0442\u043e\u0447\u0435\u043a \u0441\u0435\u0442\u043a\u0438 \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u044e\u0442\u0441\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c\u044e \u0441 \u0446\u0438\u043a\u043b\u043e\u043c, \u0430 \u043d\u0435 \u043e\u0431\u044a\u0451\u043c\u043e\u043c \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432/\u0451\u043c\u043a\u043e\u0441\u0442\u044c\u044e \u043c\u043e\u0434\u0435\u043b\u0438 (\u0447\u0438\u0441\u043b\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e \u2014 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442).\n(iii) **\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u0432\u0445\u043e\u0434\u0430:** \u0434\u043b\u044f \u0442\u043e\u0447\u0435\u043a \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440\u0430 L/period < 2 \u043f\u0440\u043e\u0433\u043e\u043d \u043f\u0440\u0438 L \u2208 {192, 336}; \u0435\u0441\u043b\u0438 \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u0435 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u043f\u0440\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0438 L \u2014 \u044d\u0444\u0444\u0435\u043a\u0442 \u043f\u0440\u0438\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0447\u0438\u0441\u043b\u0443 \u0446\u0438\u043a\u043b\u043e\u0432 \u0432\u043e \u0432\u0445\u043e\u0434\u0435, \u0430 \u043d\u0435 period \u043a\u0430\u043a \u0442\u0430\u043a\u043e\u0432\u043e\u043c\u0443.\n(iv) **\u0412\u043d\u0435\u0448\u043d\u0438\u0435 \u043d\u0430\u0438\u0432\u043d\u044b\u0435 \u043f\u0440\u0438\u0432\u044f\u0437\u043a\u0438 (\u0431\u0435\u0437 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f):** last-value ( Persistence ) \u0438 seasonal-naive \u0441 \u0441\u0443\u0442\u043e\u0447\u043d\u044b\u043c \u0446\u0438\u043a\u043b\u043e\u043c (\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0441\u0443\u0442\u043a\u0438 \u043d\u0430\u0437\u0430\u0434\u00bb, \u0448\u0430\u0433 144). \u041f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0442 \u043e\u0442\u043b\u0438\u0447\u0438\u0442\u044c \u00ab\u043b\u0443\u0447\u0448\u0435 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0435\u043c\u044c\u0438 period\u00bb \u043e\u0442 \u00ab\u043b\u0443\u0447\u0448\u0435 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430\u00bb. \u0421\u043a\u0430\u043b\u0435\u0440/\u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0434\u043b\u044f \u043d\u0438\u0445 \u2014 \u0442\u0435 \u0436\u0435, \u0447\u0442\u043e \u0434\u043b\u044f \u043c\u043e\u0434\u0435\u043b\u0438.\n\n## 7. \u041f\u0440\u0435\u0434\u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432)\n7.1 **\u0410\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f \u043f\u043e seed:** \u22653 seed \u043d\u0430 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044e (\u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043a\u043e\u0434\u0430 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u044f\u0432\u043d\u0443\u044e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u044e seed; \u0438\u043d\u0430\u0447\u0435 n=1 \u0438 \u044d\u0442\u043e \u0432\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u0432 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f). \u0418\u0442\u043e\u0433 \u043f\u043e \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u2014 **\u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u00b1 MAD \u043f\u043e seed**.\n7.2 **\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0433\u043e \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u044f:** \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 period \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u043c, \u0435\u0441\u043b\u0438 |\u0394\u043c\u0435\u0434\u0438\u0430\u043d MAE| > MAD \u043f\u043e seed \u0445\u043e\u0442\u044f \u0431\u044b \u0434\u043b\u044f \u043e\u0434\u043d\u043e\u0439 \u0438\u0437 \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u043c\u044b\u0445 \u0442\u043e\u0447\u0435\u043a (\u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0435\u0442 \u043d\u0435 \u043c\u0435\u043d\u0435\u0435 \u0447\u0435\u043c \u0434\u043b\u044f 2 \u0438\u0437 3 seed-\u043f\u0430\u0440). \u0418\u043d\u0430\u0447\u0435 \u2014 \u00ab\u043d\u0435\u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u043e\u00bb.\n7.3 **\u0427\u0442\u0435\u043d\u0438\u0435 \u043a\u0440\u0438\u0432\u043e\u0439 period \u2192 MAE:** \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u043c \u0442\u0440\u0438 \u0444\u043e\u0440\u043c\u044b: (\u0430) \u043c\u043e\u043d\u043e\u0442\u043e\u043d\u043d\u0430\u044f (\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0435 \u043a \u043c\u0430\u043b\u044b\u043c/\u0431\u043e\u043b\u044c\u0448\u0438\u043c period \u2014 \u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u043e \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430, \u0430 \u043d\u0435 \u043e \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u0441 \u0446\u0438\u043a\u043b\u043e\u043c); (\u0431) U-\u043e\u0431\u0440\u0430\u0437\u043d\u0430\u044f / \u043f\u0438\u043a\u043e\u043e\u0431\u0440\u0430\u0437\u043d\u0430\u044f \u0441 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u043e\u043c \u0432\u0431\u043b\u0438\u0437\u0438 144 (\u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0441 \u0441\u0443\u0442\u043e\u0447\u043d\u044b\u043c \u0446\u0438\u043a\u043b\u043e\u043c ETTm1 \u2014 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u043f\u0430\u0442\u0442\u0435\u0440\u043d \u0434\u043b\u044f \u043e\u0431\u0435\u0438\u0445 \u0432\u0435\u0442\u0432\u0435\u0439); (\u0432) \u043f\u043b\u043e\u0441\u043a\u0430\u044f (\u0441\u043c. 7.4). \u0422\u043e\u0447\u043a\u0430 \u00ab\u0430\u0432\u0442\u043e\u00bb \u0434\u043e\u043b\u0436\u043d\u0430, \u043f\u0440\u0438 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u0438 \u0441\u043f\u0435\u043a\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0439 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b \u0432\u0435\u0442\u043a\u0438 \u0411, \u043b\u0435\u0436\u0430\u0442\u044c \u0432\u0431\u043b\u0438\u0437\u0438 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430 \u0441\u0435\u0442\u043a\u0438; \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u00ab\u0430\u0432\u0442\u043e\u00bb \u043e\u0442 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0439 \u0444\u0430\u043a\u0442.\n7.4 **\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u044f H1:** \u0435\u0441\u043b\u0438 \u0432\u0441\u0435 \u0442\u043e\u0447\u043a\u0438 \u0441\u0435\u0442\u043a\u0438, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u00ab\u043d\u0443\u043b\u0435\u0432\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u00bb (period=37), \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442\u0441\u044f \u043c\u0435\u043d\u0435\u0435 \u0447\u0435\u043c \u043d\u0430 MAD \u043f\u043e seed (\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 7.2 \u043d\u0438\u0433\u0434\u0435 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d) \u0418 \u043a\u0440\u0438\u0432\u0430\u044f \u043f\u043b\u043e\u0441\u043a\u0430\u044f \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u00b1MAD \u2014 \u043c\u043e\u0434\u0435\u043b\u044c \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u043a period \u043d\u0430 ETTm1; H1 \u043e\u0442\u0432\u0435\u0440\u0433\u0430\u0435\u0442\u0441\u044f.\n7.5 \u041e\u0442\u0447\u0451\u0442: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 period \u00d7 H (MAE, MSE), \u043c\u0435\u0434\u0438\u0430\u043d\u0430\u00b1MAD, OT-\u0441\u0432\u043e\u0434\u043a\u0430 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e, \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0439 (i)\u2013(iv), \u0441\u0442\u0430\u0442\u0443\u0441 \u0442\u043e\u0447\u0435\u043a-\u043d\u0430\u0440\u0443\u0448\u0438\u0442\u0435\u043b\u0435\u0439 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f.\n\n## 8. \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 (\u043e\u0446\u0435\u043d\u043a\u0430 \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432, \u041d\u0415 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435)\n\u041f\u043e\u043b\u043d\u0430\u044f \u0440\u0435\u0448\u0451\u0442\u043a\u0430: 8 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 period \u00d7 4 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0430 = 32 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f (\u0432 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0435 Informer \u043a\u0430\u0436\u0434\u044b\u0439 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043e\u043d) \u00d7 3 seed = **96 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432**; + \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440 L-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u2248 3 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u00d7 3 seed = 9; + \u043d\u0430\u0438\u0432\u043d\u044b\u0435 \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u044b \u2014 \u043f\u0440\u0435\u043d\u0435\u0431\u0440\u0435\u0436\u0438\u043c\u043e. \u0418\u0442\u043e\u0433\u043e **\u043f\u043e\u0440\u044f\u0434\u043a\u0430 10\u2070\u201310\u00b9 \u0447\u0430\u0441\u043e\u0432\u2026\u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432 \u0447\u0430\u0441\u043e\u0432** \u043d\u0430 CPU \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442Architecture (\u0434\u043b\u044f \u043b\u0451\u0433\u043a\u043e\u0439 \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0439/MLP-\u043c\u043e\u0434\u0435\u043b\u0438 \u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0430 \u043f\u0440\u043e\u0433\u043e\u043d; \u0434\u043b\u044f \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0435\u0440-\u043f\u043e\u0434\u043e\u0431\u043d\u043e\u0439 \u2014 \u0447\u0430\u0441\u044b, \u0438 \u043f\u043e\u043b\u043d\u0430\u044f \u0440\u0435\u0448\u0451\u0442\u043a\u0430 \u043d\u0430 CPU \u0431\u0435\u0437 \u0441\u0435\u0442\u0438 \u0438 \u0431\u0435\u0437 GPU \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u0430 \u0437\u0430 \u0440\u0430\u0437\u0443\u043c\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f). \u042d\u0442\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432\u044b\u0435 \u043e\u0446\u0435\u043d\u043a\u0438 \u00ab\u043d\u0430 \u043f\u0430\u043b\u044c\u0446\u0430\u0445\u00bb, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0437\u0430\u043c\u0435\u0440\u043e\u0432.\n**\u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u044b\u0439 \u043f\u043e\u0434\u0441\u0435\u0442\u043e\u0447\u043d\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 (\u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043a\u043e\u0434\u0430 \u0438 \u0434\u0430\u043d\u043d\u044b\u0445):** period \u2208 {12, 24, 96, 144} + default \u00d7 \u0442\u043e\u043b\u044c\u043a\u043e H=96 \u00d7 2 seed = 10 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 + \u0441\u0435\u0437\u043e\u043d\u043d\u044b\u0439-naive/last-value + \u00ab\u043d\u0443\u043b\u0435\u0432\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u00bb 37 \u043d\u0430 H=96 (2 seed). \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0432\u0430\u043b\u0438\u0434\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043a\u043e\u043d\u0432\u0435\u0439\u0435\u0440 \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u043b\u043d\u043e\u0439 \u0440\u0435\u0448\u0451\u0442\u043a\u043e\u0439.\n**\u041e\u0444\u043b\u0430\u0439\u043d-\u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 (\u0448\u0430\u0433\u0438):** (1) \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 PDF \u0438 ETTm1.csv \u0438\u0437 \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044f/\u0430\u0440\u0445\u0438\u0432\u0430 (\u0441\u0435\u0442\u0438 \u043d\u0435\u0442); (2) \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0438\u0437 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0445 wheel-\u0430\u0440\u0445\u0438\u0432\u043e\u0432 numpy, pandas, torch (\u0438\u043b\u0438 \u0444\u0440\u0435\u0439\u043c\u0432\u043e\u0440\u043a \u0438\u0437 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f); (3) \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043f\u043e csv \u0447\u0430\u0441\u0442\u043e\u0442\u0443 (\u043c\u0435\u0434\u0438\u0430\u043d\u043d\u044b\u0439 \u0434\u0435\u043b\u044c\u0442\u0430-\u0442\u0430\u0439\u043c\u0441\u0442\u0430\u043c\u043f = 10 \u043c\u0438\u043d), \u0447\u0438\u0441\u043b\u043e \u0441\u0442\u0440\u043e\u043a (~69 680) \u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435 \u0441\u043f\u043b\u0438\u0442\u0430 6:2:2 \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u043c \u0433\u0440\u0430\u043d\u0438\u0446\u0430\u043c, \u043a\u0430\u043a \u0432 \u043a\u043e\u0434\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430; (4) \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c greppable-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u00a72; (5) smoke-run \u043d\u0430 1 \u044d\u043f\u043e\u0445\u0435 \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 wall-time \u0438 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 seed.\n\n## 9. \u041d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f \u043f\u043e \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044e (\u0444\u0430\u043a\u0442 \u043e\u0441\u043c\u043e\u0442\u0440\u0430)\n\u0415\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b \u0432 /workspace \u2014 task.json (design-only \u043f\u043e\u043c\u0435\u0442\u043a\u0430); \u043a\u043e\u0434\u0430 PDF \u043d\u0435\u0442; ETTm1 \u043d\u0435\u0442; numpy/pandas/torch/scikit/statsmodels \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b; Python 3.14.4; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430; GPU \u043d\u0435\u0442; \u043f\u043e\u0438\u0441\u043a `*ETT*` \u043f\u043e \u0424\u0421 \u043f\u0443\u0441\u0442, `*pdf*` \u0434\u0430\u0451\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0435 CUPS/qpdf-\u0443\u0442\u0438\u043b\u0438\u0442\u044b. \u0412\u0441\u0451 \u0432 \u00a7\u00a73\u20135, \u0447\u0442\u043e \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e greppable-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430\u043c\u0438 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043a\u043e\u0434\u0430, \u043e\u0441\u0442\u0430\u0451\u0442 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435\u043c.\n\n## 10. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u0438\u0445 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e\u0441\u0442\u044c\n| # | \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 | \u041a\u0430\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f/\u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0433\u0430\u0435\u0442\u0441\u044f |\n|---|---|---|\n| A1 | period = \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0446\u0438\u043a\u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438 (\u0432\u0435\u0442\u043a\u0430 \u0410 \u0438\u043b\u0438 \u0411) | \u0438\u043c\u044f \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u0430 + default \u0432 argparse/\u043a\u043e\u043d\u0444\u0438\u0433\u0435; \u043c\u0435\u0441\u0442\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0432 forward (\u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f vs FFT/top-k); assert-\u044b \u043d\u0430 seq_len |\n| A2 | \u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b: L=96, H\u2208{96,192,336,720}, MAE/MSE, \u0441\u043f\u043b\u0438\u0442 6:2:2 | \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u044b `seq_len/label_len/pred_len`; \u0431\u043b\u043e\u043a split_dataset \u0432 \u0434\u0430\u0442\u0430\u0441\u0435\u0442-\u043a\u043b\u0430\u0441\u0441\u0435 (\u0433\u0440\u0430\u043d\u0438\u0446\u044b border1/border2); \u0444\u0443\u043d\u043a\u0446\u0438\u044f metric \u0432 exp-\u043a\u043e\u0434\u0435 |\n| A3 | ETTm1: 10 \u043c\u0438\u043d, 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432, ~69 680 \u0441\u0442\u0440\u043e\u043a | pandas-\u0447\u0438\u0442\u043a\u0430 csv: diff(\u00abdate\u00bb), shape, \u0438\u043c\u0435\u043d\u0430 \u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432 (HUFL\u2026OT) |\n| A4 | \u0426\u0435\u043b\u0435\u0432\u044b\u0435 \u2014 \u0432\u0441\u0435 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432; OT \u2014 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u0443\u044e\u0449\u0438\u0439 | `c_out`/`data_dim`/\u0444\u043e\u0440\u043c\u0430 y \u0432 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0435; \u0438\u043d\u0434\u0435\u043a\u0441 \u0441\u0442\u043e\u043b\u0431\u0446\u0430 OT; OT-\u0441\u0432\u043e\u0434\u043a\u0430 \u00a75 |\n| A5 | \u00ab\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u00bb = \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430 | \u043f\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0437\u0430\u0434\u0430\u0447\u0438/\u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0432 README+exp; \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0431\u043e\u0447\u043d\u043e |\n| A6 | \u041f\u043e\u0432\u0442\u043e\u0440\u044b \u043f\u043e seed \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b (\u22653) | \u043d\u0430\u043b\u0438\u0447\u0438\u0435 seed-\u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u0430/\u0441\u0438\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0432 \u043a\u043e\u0434\u0435; \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u2014 n=1 \u0432 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u0445 |\n| A7 | \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 seq_len \u2265 2\u00b7period \u2014 \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u043e\u0435 (\u0438\u0437 \u043a\u043e\u0434\u0430 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e) | grep assert/raise \u0441 period \u0438 seq_len \u0432 \u043a\u043e\u0434\u0435; \u043f\u0440\u0438 \u0436\u0451\u0441\u0442\u043a\u043e\u043c assert \u0432 code \u2014 \u0442\u043e\u0447\u043a\u0438-\u043d\u0430\u0440\u0443\u0448\u0438\u0442\u0435\u043b\u0438 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0438 \u044d\u0442\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f |\n\n**\u041f\u043e\u0432\u0442\u043e\u0440\u043d\u043e \u0438 \u044f\u0432\u043d\u043e: \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f; \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0435\u0434\u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u043c. \u0412\u0441\u0435 \u0447\u0438\u0441\u043b\u0430 \u0441\u0435\u0442\u043e\u043a/\u0441\u043f\u043b\u0438\u0442\u043e\u0432/\u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 \u0434\u043e \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043a\u043e\u0434\u0430 \u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u2014 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0441 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0449\u0438\u043c\u0438 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430\u043c\u0438, \u0430 \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f.**", "evidence": "\u0424\u0430\u043a\u0442\u044b \u043e\u0441\u043c\u043e\u0442\u0440\u0430 (\u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u043e \u0434\u0432\u0430\u0436\u0434\u044b \u0437\u0430 \u0441\u0435\u0441\u0441\u0438\u044e, \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e): 1) /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json; \u043f\u043e\u0434\u043a\u0430\u0442\u0430\u043b\u043e\u0433\u043e\u0432 \u0438 \u0441\u043a\u0440\u044b\u0442\u044b\u0445 \u0444\u0430\u0439\u043b\u043e\u0432 \u043d\u0435\u0442; task.json \u043f\u043e\u043c\u0435\u0447\u0435\u043d design-only, datasets=[]. 2)\u5168\u76d8\u043d\u044b\u0439 \u043f\u043e\u0438\u0441\u043a: `find / -iname '*ETT*'` \u2014 \u043f\u0443\u0441\u0442\u043e; `*pdf*` \u0432\u043d\u0435 /usr,/proc,/sys \u2014 \u0442\u043e\u043b\u044c\u043a\u043e CUPS/qpdf (\u043d\u0435 \u043e\u0442\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u043a \u0437\u0430\u0434\u0430\u0447\u0435). 3) \u0417\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438: `pip list | grep -iE 'numpy|pandas|torch|scikit|scipy|statsmodels'` \u2014 \u043f\u0443\u0441\u0442\u043e; \u0438\u043c\u043f\u043e\u0440\u0442 numpy/torch/pandas \u2192 ModuleNotFoundError; Python 3.14.4; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 (per \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f), GPU \u043d\u0435\u0442. \u0421\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e: \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u043a\u0430 period, default-\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u0438 \u0438 \u0441\u043e\u0441\u0442\u0430\u0432 \u0446\u0435\u043b\u0435\u0432\u044b\u0445 \u043a\u0430\u043d\u0430\u043b\u043e\u0432 \u041d\u0415 \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u044b \u2014 \u0432 \u043f\u0440\u043e\u0435\u043a\u0442\u0435 \u043e\u043d\u0438 \u043e\u0444\u043e\u0440\u043c\u043b\u0435\u043d\u044b \u043a\u0430\u043a \u0443\u0441\u043b\u043e\u0432\u043d\u0430\u044f \u0440\u0430\u0437\u0432\u0438\u043b\u043a\u0430 (\u00a72) \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u00a710) \u0441 greppable-\u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430\u043c\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f. \u0427\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 ETTm1 \u0438 ETT-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 \u0432\u0437\u044f\u0442\u044b \u043a\u0430\u043a \u0432\u043d\u0435\u0448\u043d\u0438\u0435 \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b. \u041e\u0446\u0435\u043d\u043a\u0438 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u0432 \u00a78 \u2014 \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432\u044b\u0435, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0437\u0430\u043c\u0435\u0440\u043e\u0432. \u041d\u0438\u043a\u0430\u043a\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 \u043d\u0435 \u043e\u0431\u0443\u0447\u0430\u043b\u0441\u044f; \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043d\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u043b\u0438\u0441\u044c.", "assumptions": ["A1: period \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0446\u0438\u043a\u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438 (\u0432\u0435\u0442\u043a\u0430 \u0410: \u0446\u0438\u043a\u043b \u0441\u0435\u0437\u043e\u043d\u043d\u043e\u0439 \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u0438/\u0441\u043a\u043e\u043b\u044c\u0437\u044f\u0449\u0435\u0433\u043e \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0438\u044f; \u0432\u0435\u0442\u043a\u0430 \u0411: \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u043f\u0435\u0440\u0438\u043e\u0434/override \u043f\u043e\u0441\u043b\u0435 \u0441\u043f\u0435\u043a\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0438); \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u2014 \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u0430, default \u0438 \u043c\u0435\u0441\u0442\u0443 \u0432 forward-\u0433\u0440\u0430\u0444\u0435", "A2: \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b ETT-\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430 \u2014 L=96, H\u2208{96,192,336,720}, \u0445\u0440\u043e\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043f\u043b\u0438\u0442 6:2:2, \u0441\u043a\u0430\u043b\u0435\u0440 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 train; \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u043e \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u0430\u043c \u0438 \u043a\u043e\u0434\u0443 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430", "A3: ETTm1 \u2014 10-\u043c\u0438\u043d\u0443\u0442\u043d\u044b\u0439 \u0440\u044f\u0434, 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432, ~69 680 \u0441\u0442\u0440\u043e\u043a \u0437\u0430 2016\u20132018; \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0447\u0438\u0442\u043a\u043e\u0439 ETTm1.csv \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f", "A4: \u0446\u0435\u043b\u0435\u0432\u044b\u043c\u0438 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0432\u0441\u0435 7 \u043a\u0430\u043d\u0430\u043b\u043e\u0432 (c_out=7), OT \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0441\u0432\u043e\u0434\u043a\u043e